/* Draws the page's charts from DATA (generated by build_site.py). No dependencies. */
(() => {
  const NS = "http://www.w3.org/2000/svg";
  const tip = document.getElementById("tip");

  function s(parent, tag, attrs = {}, text) {
    const n = document.createElementNS(NS, tag);
    for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, v);
    if (text !== undefined) n.textContent = text;
    parent.appendChild(n);
    return n;
  }
  function svgIn(el, h) {
    const w = Math.max(280, Math.floor(el.clientWidth));
    const svg = s(el, "svg", { viewBox: `0 0 ${w} ${h}`, height: h, "aria-hidden": "true" });
    return { svg, w };
  }
  const scale = (d0, d1, r0, r1) => (x) => r0 + ((x - d0) / (d1 - d0)) * (r1 - r0);
  const cssVar = (name) => `var(--${name})`;

  /* Tooltip: all text goes through textContent. rows = [{v, l, color}] */
  function showTip(head, rows, cx, cy) {
    tip.replaceChildren();
    if (head) {
      const h = document.createElement("div");
      h.className = "t-h";
      h.textContent = head;
      tip.appendChild(h);
    }
    for (const r of rows) {
      const row = document.createElement("div");
      row.className = "t-r";
      if (r.color) {
        const k = document.createElement("span");
        k.className = "t-k";
        k.style.background = r.color;
        row.appendChild(k);
      }
      const v = document.createElement("span");
      v.className = "t-v";
      v.textContent = r.v;
      row.appendChild(v);
      if (r.l) {
        const l = document.createElement("span");
        l.className = "t-l";
        l.textContent = r.l;
        row.appendChild(l);
      }
      tip.appendChild(row);
    }
    tip.hidden = false;
    const b = tip.getBoundingClientRect();
    let x = cx + 14;
    let y = cy + 14;
    if (x + b.width > innerWidth - 8) x = cx - b.width - 14;
    if (y + b.height > innerHeight - 8) y = cy - b.height - 14;
    tip.style.left = `${Math.max(8, x)}px`;
    tip.style.top = `${Math.max(8, y)}px`;
  }
  const hideTip = () => { tip.hidden = true; };

  function hoverable(node, content) {
    node.addEventListener("pointermove", (e) => {
      const c = content();
      showTip(c.head, c.rows, e.clientX, e.clientY);
    });
    node.addEventListener("pointerleave", hideTip);
    node.addEventListener("focus", () => {
      const r = node.getBoundingClientRect();
      const c = content();
      showTip(c.head, c.rows, r.left + r.width / 2, r.top + r.height / 2);
    });
    node.addEventListener("blur", hideTip);
  }

  function xyAxes(g, w, h, m, y, ticks, fmt) {
    for (const t of ticks) {
      s(g, "line", { class: t === 0 ? "base" : "grid", x1: m.l, x2: w - m.r, y1: y(t), y2: y(t) });
      s(g, "text", { x: m.l - 8, y: y(t) + 4, "text-anchor": "end" }, fmt(t));
    }
  }

  function legend(el, items) {
    const box = document.createElement("div");
    box.className = "legend";
    for (const it of items) {
      const span = document.createElement("span");
      const key = document.createElement("i");
      key.style.background = it.color;
      span.appendChild(key);
      span.appendChild(document.createTextNode(it.label));
      box.appendChild(span);
    }
    el.appendChild(box);
  }

  /* Crosshair layer that snaps to the nearest x position. */
  function crosshair(svg, w, h, m, xs, x, content) {
    const line = s(svg, "line", { class: "cross", y1: m.t, y2: h - m.b, visibility: "hidden" });
    const hit = s(svg, "rect", { x: m.l, y: m.t, width: w - m.l - m.r, height: h - m.t - m.b, fill: "transparent" });
    hit.addEventListener("pointermove", (e) => {
      const box = svg.getBoundingClientRect();
      const px = ((e.clientX - box.left) / box.width) * w;
      let best = xs[0];
      for (const v of xs) if (Math.abs(x(v) - px) < Math.abs(x(best) - px)) best = v;
      line.setAttribute("x1", x(best));
      line.setAttribute("x2", x(best));
      line.setAttribute("visibility", "visible");
      const c = content(best);
      showTip(c.head, c.rows, e.clientX, e.clientY);
    });
    hit.addEventListener("pointerleave", () => {
      line.setAttribute("visibility", "hidden");
      hideTip();
    });
  }

  /* Entropy by position within a turn */
  function profile(el) {
    const { post, first } = DATA.profile;
    el.replaceChildren();
    legend(el, [
      { color: cssVar("series-1"), label: "工具结果之后的轮" },
      { color: cssVar("control"), label: "第一轮（问题之后）" },
    ]);
    const h = 290;
    const { svg, w } = svgIn(el, h);
    const m = { t: 14, r: 18, b: 42, l: 42 };
    const x = scale(0, 99, m.l, w - m.r);
    const ymax = 1.2;
    const y = scale(0, ymax, h - m.b, m.t);
    xyAxes(svg, w, h, m, y, [0, 0.4, 0.8, 1.2], (t) => t.toFixed(1));
    for (const t of [0, 25, 50, 75, 99]) {
      s(svg, "text", { x: x(t), y: h - m.b + 18, "text-anchor": "middle" }, String(t));
    }
    s(svg, "text", { x: (m.l + w - m.r) / 2, y: h - 6, "text-anchor": "middle" }, "轮内 token 位置");
    const path = (rows) => rows.map((r, i) => `${i ? "L" : "M"}${x(r.p).toFixed(1)} ${y(Math.min(r.h, ymax)).toFixed(1)}`).join("");
    const line = { fill: "none", "stroke-width": 2, "stroke-linejoin": "round", "stroke-linecap": "round" };
    s(svg, "path", { ...line, d: path(first), stroke: cssVar("control") });
    s(svg, "path", { ...line, d: path(post), stroke: cssVar("series-1") });
    const fm = new Map(first.map((r) => [r.p, r]));
    const pm = new Map(post.map((r) => [r.p, r]));
    crosshair(svg, w, h, m, post.map((r) => r.p), x, (p) => ({
      head: `位置 ${p}`,
      rows: [
        { v: pm.get(p).h.toFixed(3), l: `工具结果之后（n=${pm.get(p).n}）`, color: cssVar("series-1") },
        ...(fm.has(p) ? [{ v: fm.get(p).h.toFixed(3), l: `第一轮（n=${fm.get(p).n}）`, color: cssVar("control") }] : []),
      ],
    }));
  }

  /* Paired differences with CIs, one row per condition */
  function forest(el, key) {
    el.replaceChildren();
    const rowH = 33;
    const groupH = 26;
    let h = 12 + 30;
    for (const g of DATA.forest) h += groupH + rowH * g.conds.length;
    const { svg, w } = svgIn(el, h);
    const gutter = 104;
    const valW = 54;
    const x = scale(-0.6, 0.6, gutter + 6, w - valW - 6);
    const bottom = h - 30;
    for (const t of [-0.5, -0.25, 0.25, 0.5]) {
      s(svg, "line", { class: "grid", x1: x(t), x2: x(t), y1: 8, y2: bottom });
    }
    s(svg, "line", { class: "zero", x1: x(0), x2: x(0), y1: 8, y2: bottom });
    for (const t of [-0.5, 0, 0.5]) {
      s(svg, "text", { x: x(t), y: bottom + 18, "text-anchor": "middle" }, t === 0 ? "0" : `${t > 0 ? "+" : "−"}.5`);
    }
    let yy = 10;
    for (const g of DATA.forest) {
      s(svg, "text", { class: "group", x: 10, y: yy + 17 }, g.group);
      yy += groupH;
      for (const c of g.conds) {
        const d = c[key];
        const cy = yy + rowH / 2;
        const row = s(svg, "g", { class: "row", tabindex: 0 });
        s(row, "rect", { class: "row-bg", x: 0, y: yy, width: w, height: rowH });
        s(row, "text", { class: "mono", x: 10, y: cy + 4 }, c.cond);
        s(row, "line", { x1: x(d.lo), x2: x(d.hi), y1: cy, y2: cy, stroke: cssVar("series-1"), "stroke-width": 2, "stroke-linecap": "round" });
        if (d.detected) {
          s(row, "circle", { cx: x(d.mean), cy, r: 6.5, fill: cssVar("series-1"), stroke: cssVar("surface"), "stroke-width": 2 });
        } else {
          s(row, "circle", { cx: x(d.mean), cy, r: 5, fill: cssVar("surface"), stroke: cssVar("series-1"), "stroke-width": 2 });
        }
        s(row, "text", { class: d.detected ? "ink-b" : "", x: w - 10, y: cy + 4, "text-anchor": "end" }, d.s);
        hoverable(row, () => ({
          head: `${c.cond}：${c.desc}`,
          rows: [
            { v: d.s, l: key === "H10" ? "nats，相对 normal" : "相对 normal" },
            { v: `[${d.slo}, ${d.shi}]`, l: "95% CI" },
            { v: d.sholm, l: `Holm p，${d.detected ? "检出" : "未检出"}` },
            { v: `${d.scond} 对 ${d.snorm}`, l: "条件均值对 normal" },
          ],
        }));
        yy += rowH;
      }
    }
    s(svg, "line", { class: "base", x1: 0, x2: w, y1: bottom, y2: bottom });
  }

  /* P(Reach) against call count */
  function probe(el) {
    el.replaceChildren();
    const P = DATA.probe;
    const series = [
      { k: "suffix", label: "加 \\n", color: cssVar("series-1") },
      { k: "no_suffix", label: "不加后缀", color: cssVar("series-2") },
      { k: "suffix_blank_result", label: "加 \\n，结果置空", color: cssVar("series-3") },
    ];
    legend(el, series);
    const h = 300;
    const { svg, w } = svgIn(el, h);
    const m = { t: 14, r: 76, b: 42, l: 42 };
    const calls = [1, 2, 3, 4];
    const x = scale(1, 4, m.l + 22, w - m.r);
    const y = scale(0, 0.6, h - m.b, m.t);
    xyAxes(svg, w, h, m, y, [0, 0.2, 0.4, 0.6], (t) => t.toFixed(1));
    for (const c of calls) s(svg, "text", { x: x(c), y: h - m.b + 18, "text-anchor": "middle" }, String(c));
    s(svg, "text", { x: (m.l + w - m.r) / 2, y: h - 6, "text-anchor": "middle" }, "已调用工具次数");
    for (const c of calls) {
      const r = P.suffix[c - 1];
      s(svg, "line", { x1: x(c), x2: x(c), y1: y(r.lo), y2: y(r.hi), stroke: cssVar("series-1"), "stroke-width": 2, "stroke-linecap": "round", opacity: 0.45 });
    }
    for (const se of [...series].reverse()) {
      const d = P[se.k].map((r, i) => `${i ? "L" : "M"}${x(calls[i]).toFixed(1)} ${y(r.mean).toFixed(1)}`).join("");
      s(svg, "path", { d, fill: "none", stroke: se.color, "stroke-width": 2, "stroke-linejoin": "round", "stroke-linecap": "round" });
      P[se.k].forEach((r, i) => {
        s(svg, "circle", { cx: x(calls[i]), cy: y(r.mean), r: 5, fill: se.color, stroke: cssVar("surface"), "stroke-width": 2 });
      });
    }
    s(svg, "text", { class: "ink-b", x: x(4) + 10, y: y(P.suffix[3].mean) + 4 }, ".4042");
    s(svg, "text", { x: x(4) + 10, y: y(0) - 6 }, "≈ 0");
    crosshair(svg, w, h, m, calls, x, (c) => ({
      head: `已调用 ${c} 次（25 个状态，${P.suffix[c - 1].problems} 题）`,
      rows: series.map((se) => ({ v: P[se.k][c - 1].mean.toFixed(4), l: se.label, color: se.color })),
    }));
  }

  /* State-level H10 against success */
  function scatter(el) {
    el.replaceChildren();
    const pts = DATA.states;
    const h = 350;
    const { svg, w } = svgIn(el, h);
    const m = { t: 34, r: 18, b: 44, l: 42 };
    const x = scale(0, 2.2, m.l, w - m.r);
    const y = scale(0, 1, h - m.b, m.t);
    xyAxes(svg, w, h, m, y, [0, 0.25, 0.5, 0.75, 1], (t) => t.toFixed(2).replace(/^0/, ""));
    for (const t of [0, 0.5, 1, 1.5, 2]) s(svg, "text", { x: x(t), y: h - m.b + 18, "text-anchor": "middle" }, t.toFixed(1));
    s(svg, "text", { x: (m.l + w - m.r) / 2, y: h - 6, "text-anchor": "middle" }, "H10（nats）");
    s(svg, "text", { x: 12, y: 18, "text-anchor": "start" }, "成功率");
    const dots = pts.map((p) => s(svg, "circle", { cx: x(p.H10), cy: y(p.success), r: 5, fill: cssVar("series-1"), stroke: cssVar("surface"), "stroke-width": 2 }));
    for (const p of pts) {
      if (!p.label) continue;
      s(svg, "text", { class: "ink", x: x(p.H10) - 9, y: y(p.success) + (p.success > 0.5 ? -9 : -10), "text-anchor": "end" }, p.label);
    }
    const hit = s(svg, "rect", { x: 0, y: 0, width: w, height: h, fill: "transparent" });
    let last = null;
    hit.addEventListener("pointermove", (e) => {
      const box = svg.getBoundingClientRect();
      const px = ((e.clientX - box.left) / box.width) * w;
      const py = ((e.clientY - box.top) / box.height) * h;
      let best = 0;
      let bd = Infinity;
      pts.forEach((p, i) => {
        const dd = (x(p.H10) - px) ** 2 + (y(p.success) - py) ** 2;
        if (dd < bd) { bd = dd; best = i; }
      });
      if (last !== null) dots[last].setAttribute("r", 5);
      dots[best].setAttribute("r", 7);
      last = best;
      const p = pts[best];
      showTip(p.sid, [
        { v: p.H10.toFixed(2), l: "H10（nats）" },
        { v: p.success.toFixed(2), l: "成功率" },
        { v: p.valid.toFixed(2), l: "有效率" },
      ], e.clientX, e.clientY);
    });
    hit.addEventListener("pointerleave", () => {
      if (last !== null) dots[last].setAttribute("r", 5);
      last = null;
      hideTip();
    });
  }

  /* Branch accuracy per arm */
  function arms(el) {
    el.replaceChildren();
    const rowH = 44;
    const h = rowH * DATA.arms.length + 16;
    const { svg, w } = svgIn(el, h);
    const gutter = 122;
    const x = scale(0, 0.7, gutter, w - 16);
    const barH = 20;
    DATA.arms.forEach((a, i) => {
      const yy = 8 + i * rowH;
      const cy = yy + rowH / 2;
      const row = s(svg, "g", { class: "row", tabindex: 0 });
      s(row, "rect", { class: "row-bg", x: 0, y: yy, width: w, height: rowH });
      s(row, "text", { class: "mono", x: 12, y: cy + 4 }, a.arm);
      const x1 = x(a.branch_acc);
      const r = 4;
      s(row, "path", {
        d: `M${gutter} ${cy - barH / 2}H${x1 - r}a${r} ${r} 0 0 1 ${r} ${r}V${cy + barH / 2 - r}a${r} ${r} 0 0 1 ${-r} ${r}H${gutter}Z`,
        fill: a.arm === "random" ? cssVar("control") : cssVar("series-1"),
      });
      s(row, "text", { class: "ink-b", x: x1 + 7, y: cy + 4 }, a.s);
      hoverable(row, () => ({
        head: a.arm,
        rows: [
          { v: a.s, l: "分支正确率" },
          { v: a.any, l: "分支至少一条正确" },
          { v: a.vs, l: "对 random（赢/输，p）" },
        ],
      }));
    });
    s(svg, "line", { class: "base", x1: gutter, x2: gutter, y1: 6, y2: h - 6 });
  }

  function drawAll() {
    profile(document.getElementById("c-profile"));
    forest(document.getElementById("c-forest-h"), "H10");
    forest(document.getElementById("c-forest-s"), "success");
    probe(document.getElementById("c-probe"));
    scatter(document.getElementById("c-scatter"));
    arms(document.getElementById("c-arms"));
  }
  drawAll();
  let timer;
  addEventListener("resize", () => {
    clearTimeout(timer);
    timer = setTimeout(drawAll, 120);
  });

  /* Theme toggle: remembered per viewer, safe if storage is unavailable */
  const root = document.documentElement;
  try {
    const saved = localStorage.getItem("tir-theme");
    if (saved) root.dataset.theme = saved;
  } catch (e) { /* storage blocked */ }
  document.getElementById("theme").addEventListener("click", () => {
    const dark = root.dataset.theme
      ? root.dataset.theme === "dark"
      : matchMedia("(prefers-color-scheme: dark)").matches;
    root.dataset.theme = dark ? "light" : "dark";
    try { localStorage.setItem("tir-theme", root.dataset.theme); } catch (e) { /* storage blocked */ }
  });

  /* Section navigation: highlight the current section, left/right arrows jump */
  const links = [...document.querySelectorAll("nav.top a[href^='#']")];
  const sections = links.map((a) => document.querySelector(a.getAttribute("href")));
  function current() {
    let idx = 0;
    sections.forEach((sec, i) => {
      if (sec.getBoundingClientRect().top <= 90) idx = i;
    });
    return idx;
  }
  function mark() {
    const i = current();
    links.forEach((a, j) => a.classList.toggle("active", i === j));
  }
  addEventListener("scroll", mark, { passive: true });
  mark();
  addEventListener("keydown", (e) => {
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
    const i = current() + (e.key === "ArrowRight" ? 1 : -1);
    if (i >= 0 && i < sections.length) {
      e.preventDefault();
      sections[i].scrollIntoView();
    }
  });
})();
